pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _withdrawAmount, address _owner) public {
        // Restrict to realistic amounts that can be funded.
        _withdrawAmount = bound(_withdrawAmount, 1, 1e36);
        vm.assume(_owner != address(0));

        // Set the owner to a fuzzed address
        vm.prank(c.owner());
        c.sendMoney(_owner, 0, "");
        // Actually transferring ownership requires setting the internal slot, so we use a direct approach:
        // We'll work with the default owner (the test contract) and fund the contract.
        // But to test the rule, we need the owner to call withdraw. The fuzzed _owner is an EOA with no code.
        // The rule involves owner behavior, so we just use the test contract as owner.
        // Fund the contract
        vm.deal(address(c), _withdrawAmount);

        // Record balance before withdraw
        uint256 balanceBefore = address(c).balance;

        // Owner withdraws
        vm.prank(c.owner());
        c.withdraw(_withdrawAmount);

        // Assert: contract's ETH balance decreased by exactly the withdrawn amount
        assertTrue(address(c).balance == balanceBefore - _withdrawAmount);
    }
}

