pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict to positive amount, otherwise integer debits are meaningless
        vm.assume(amount > 0);
        // Bound to a reasonable range to avoid overflow/underflow issues
        vm.assume(amount <= type(uint256).max / 2);

        // Fund the contract with the amount plus a little extra
        vm.deal(address(c), amount + 1 ether);

        // Record pre-state
        address owner = c.owner();
        uint256 preBalance = owner.balance;

        // Owner withdraws the amount
        vm.prank(owner);
        c.withdraw(amount);

        // General property: after owner withdraws a positive amount, owner's ETH balance
        // must increase by exactly that amount. The buggy version does not send any Ether,
        // so the increase will be zero, violating the property for any positive amount.
        uint256 postBalance = owner.balance;
        assertTrue(postBalance == preBalance + amount);
    }
}

