        // (owner must have sufficient balance). The mutant sends 0 regardless, so any
        // amount > 0 triggers the difference; amount == 0 is benign and admissible.
        vm.assume(amount > 0);
        // Give the contract enough Ether so the legitimate call to transfer(amount)
        // in the reference implementation would succeed (and the mutant sends 0).
        vm.deal(address(c), amount);
        // Record contract balance before withdrawal.
        uint256 balBefore = address(c).balance;
        // Owner calls withdraw.
        vm.prank(c.owner());
        c.withdraw(amount);
        // Record contract balance after withdrawal.
        uint256 balAfter = address(c).balance;
        // The invariant: contract balance must decrease by exactly amount.
        // The reference implementation decreases by amount; the mutant sends 0,
        // so balance stays the same, violating this invariant.
        assertTrue(balBefore - balAfter == amount);
    }
}

